#!/usr/bin/env python3
"""Corrige la web antes de publicar; falla si el paquete web no coincide con lo esperado.
No contiene secretos, datos clinicos ni cambios en el Excel original.
"""
from pathlib import Path
import json

PATCHES = json.loads(r'''[{"path":"cloud.js","label":"colecciones remotas","old":"const tables=new Set(['records','shifts','freezers','audit']);","next":"const tables=new Set(['records','shifts','freezers','audit']);\nconst readableTables=new Set([...tables,'mirrors']);"},{"path":"cloud.js","label":"formato REST de Firestore","old":"return `${base()}/owners/${safe(session.uid)}/entries/${hex}`;","next":"return `projects/${safe(config.projectId)}/databases/(default)/documents/owners/${safe(session.uid)}/entries/${hex}`;"},{"path":"cloud.js","label":"capturas remotas permitidas","old":"if(!tables.has(table)||typeof id!=='string'||!revision||typeof payload!=='string')","next":"if(!readableTables.has(table)||typeof id!=='string'||!revision||typeof payload!=='string')"},{"path":"cloud.js","label":"consulta documento remoto","old":"async function fetchOne(name){try{return await request(name);}","next":"async function fetchOne(name){try{return await request('https://firestore.googleapis.com/v1/'+name);}"},{"path":"cloud.js","label":"leer capturas OneDrive","old":"   await applyCloudRow(value.table,value.id,value.row,{revision:value.revision,updateTime:value.updateTime,syncedAt:value.syncedAt});","next":"   if(value.table==='mirrors'){\n    // Capturas remotas pendientes de revisión; no confirman congelación.\n    const r=value.row;\n    if(!r||typeof r.data!=='object'||r.data===null||typeof r.sourceSheet!=='string')throw Error('Captura remota inválida.');\n    const previous=await one('captures',value.id);\n    const changed=!previous||JSON.stringify(previous.data)!==JSON.stringify(r.data);\n    const copy={...r,id:value.id,sourceOrigin:'onedrive',\n     importedAt:previous?.importedAt||r.importedAt||null,\n     importedRecordId:previous?.importedRecordId||r.importedRecordId||null,\n     dismissedAt:changed?null:(previous?.dismissedAt||r.dismissedAt||null),\n     reviewedAt:changed?null:(previous?.reviewedAt||r.reviewedAt||null),\n     reviewNote:changed&&previous?.importedAt?'El archivo cambió después de importar esta fila. Comprueba los datos antes de usarla.':r.reviewNote||null};\n    await put('captures',copy);\n   }else{\n    await applyCloudRow(value.table,value.id,value.row,{revision:value.revision,updateTime:value.updateTime,syncedAt:value.syncedAt});\n   }"},{"path":"app.js","label":"orden capturas","old":"rows=S.captures.slice().sort((a,b)=>(b.sourceEventId||0)-(a.sourceEventId||0)).slice(0,80)","next":"rows=S.captures.slice().sort((a,b)=>String(b.timestamp||'').localeCompare(String(a.timestamp||''))).slice(0,80)"},{"path":"app.js","label":"titulo sincronizacion","old":"heading('Sincronización y recuperación','Capturas locales de Excel y revisión antes de incorporar al inventario'","next":"heading('Sincronización y recuperación','Capturas de Excel (locales o autorizadas desde la nube), pendientes de revisión'"},{"path":"app.js","label":"estado real OneDrive","old":"${renderCloudPanel()}<section class=\"card sync-box\">","next":"${renderCloudPanel()}<section class=\"card\"><div class=\"card-head\"><h3>OneDrive personal de Outlook</h3><span class=\"badge warn\">Pendiente de autorización Microsoft</span></div><p class=\"small muted\">La lectura automática de tu copia del Excel se está preparando de forma independiente del capturador Windows. Todavía no hay acceso autorizado a OneDrive ni importación automática; no es necesario instalar Azure. Cuando esté activada, las filas llegarán como capturas pendientes de revisión, nunca como congelaciones confirmadas.</p></section><section class=\"card sync-box\">"},{"path":"sw.js","label":"actualizacion cache PWA","old":"const CACHE='mis-alicuotas-shell-github-1';","next":"const CACHE='mis-alicuotas-shell-github-2';"}]''')
root = Path("site")
changes = {}
for item in PATCHES:
    path = root / item["path"]
    if not path.is_file():
        raise RuntimeError("No existe el archivo web: " + str(path))
    source = changes.get(item["path"], path.read_text(encoding="utf-8"))
    matches = source.count(item["old"])
    if matches != 1:
        raise RuntimeError(f"Parche {item['label']}: esperado 1 coincidencia, encontrado {matches}")
    changes[item["path"]] = source.replace(item["old"], item["next"], 1)
for name, updated in changes.items():
    (root / name).write_text(updated, encoding="utf-8")
print("Correcciones web listas: Firestore y recepcion remota OneDrive pendientes de activar.")
